The graph shows $A:y=x+1$, $B:y=-x+7$ and $C:y=2x-3$. Use the intersection of lines $A$ and $B$ to solve their equations simultaneously.
[tikz]
\begin{tikzpicture}[x=10mm,y=10mm,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\definecolor{seriesBlue}{HTML}{268CFF}
\definecolor{seriesRed}{HTML}{EF6068}
\definecolor{seriesGreen}{HTML}{4F9B63}
\draw[draw=black!20,xstep=10mm,ystep=10mm] (-1,-3) grid (6,7);
\draw[<->,black] (-1.3,0)--(6.3,0) node[right] {$x$};
\draw[<->,black] (0,-3.3)--(0,7.3) node[above] {$y$};
\foreach \v in {-1,1,2,3,4,5,6} {\draw[black] (\v,0.07)--(\v,-0.07);\path (\v,-0.1) node[below,font=\fontsize{8.5}{10}\selectfont] {$\v$};}
\foreach \v in {-3,-2,-1,1,2,3,4,5,6,7} {\draw[black] (0.07,\v)--(-0.07,\v);\path (-0.1,\v) node[left,font=\fontsize{8.5}{10}\selectfont] {$\v$};}
\path (-0.1,-0.1) node[below left,font=\fontsize{8.5}{10}\selectfont] {$0$};
\draw[seriesBlue,thick,<->] (-1,0)--(6,7);
\draw[seriesRed,thick,dashed,<->] (0,7)--(6,1);
\draw[seriesGreen,thick,dotted,<->] (0,-3)--(5,7);
\path (5.7,6.7) node[left,text=seriesBlue] {$A$};
\path (5.7,1.3) node[above,text=seriesRed] {$B$};
\path (4.8,6.6) node[left,text=seriesGreen] {$C$};
\end{tikzpicture}
[/tikz]
